import React,{useEffect,useState} from "react";

export default function AdminDashboard({api,token}){

const[leaves,setLeaves] = useState([]);

const loadLeaves = async()=>{

const res = await fetch(api+"/leaves/all");

const data = await res.json();

setLeaves(data);

};

useEffect(()=>{
loadLeaves();
},[]);

const approve = async(id)=>{

await fetch(api+"/leaves/approve/"+id,{
method:"PUT"
});

loadLeaves();

};

const reject = async(id)=>{

await fetch(api+"/leaves/reject/"+id,{
method:"PUT"
});

loadLeaves();

};

return(

<div>

<h2>Admin Dashboard</h2>

{leaves.map(l=>(

<div key={l._id}>

<p>{l.reason}</p>

<p>Status: {l.status}</p>

<button onClick={()=>approve(l._id)}>
Approve
</button>

<button onClick={()=>reject(l._id)}>
Reject
</button>

</div>

))}

</div>

)

}
